import{_ as e,o as a,c as l,b6 as i}from"./chunks/framework.BUXTSoD9.js";const x=JSON.parse('{"title":"專案介紹","description":"","frontmatter":{},"headers":[],"relativePath":"zh-tw/guide/introduction.md","filePath":"zh-tw/guide/introduction.md"}'),d={name:"zh-tw/guide/introduction.md"};function n(r,t,s,g,h,f){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="專案介紹" tabindex="-1">專案介紹 <a class="header-anchor" href="#專案介紹" aria-label="Permalink to “專案介紹”">​</a></h1><p>2025年，被很多人視為AI程式設計的元年。越來越多的人開始用AI寫程式碼，但往往做出來的還停留在玩具層面——不知道如何用Vibe Coding組織開發流程，不知道該選哪些工具，更不清楚從原型到上線中間還差哪些關鍵步驟。</p><p>我們採用循序漸進的<strong>三階段實戰路徑</strong>：新手入門階段透過小遊戲快速上手AI程式設計，第一階段掌握Vibe Coding工作方式並完成Web應用原型，第二階段學習全棧開發與部署上線，第三階段構建跨平臺複雜應用。</p><p>每個階段都配有完整專案實戰，讓你在真實挑戰中從玩具走向產品，最終具備<strong>將任何想法落地為可用應用</strong>的能力。</p><p>我們相信，掌握Vibe Coding並配合系統化訓練，你一個人就能成為<strong>集前後端開發、AI能力整合、產品設計於一身的全能開發者</strong>。</p><p>本專案主要面向三類學習者：</p><ul><li><strong>新手（普通人 / 產品與運營側）</strong>：幫助非技術背景角色和入門學習者聽懂關鍵概念，完成第一個 AI 小工具或產品原型。</li><li><strong>初中級開發者（有一定基礎的學生和開發者）</strong>：系統掌握 vibe coding 與原生 AI 應用開發。</li><li><strong>高階開發者（公司與初創、開源與獨立開發者）</strong>：支援團隊和個人快速搭建、驗證與迭代原生 AI 應用。</li></ul><h2 id="📖-內容導航" tabindex="-1">📖 內容導航 <a class="header-anchor" href="#📖-內容導航" aria-label="Permalink to “📖 內容導航”">​</a></h2><h3 id="總附錄" tabindex="-1">總附錄 <a class="header-anchor" href="#總附錄" aria-label="Permalink to “總附錄”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/zh-tw/appendix/8-artificial-intelligence/ai-capability-dictionary.html">AI 能力詞典：常見 AI 核心概念與名詞、場景解釋</a></p><h3 id="零、幼兒園" tabindex="-1">零、幼兒園 <a class="header-anchor" href="#零、幼兒園" aria-label="Permalink to “零、幼兒園”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">章節</th><th style="text-align:left;">關鍵內容</th><th style="text-align:left;">狀態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/learning-map/">新手入門：學習地圖</a></td><td style="text-align:left;">整體學習路徑導覽</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/ai-capabilities-through-games/">新手入門：AI 時代，會說話就會程式設計</a></td><td style="text-align:left;">透過貪喫蛇等案例初步感受 AI 程式設計的能力</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="一、ai-產品經理" tabindex="-1">一、AI 產品經理 <a class="header-anchor" href="#一、ai-產品經理" aria-label="Permalink to “一、AI 產品經理”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">章節</th><th style="text-align:left;">關鍵內容</th><th style="text-align:left;">狀態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/introduction-to-ai-ide/">初級二：認識 AI IDE 工具</a></td><td style="text-align:left;">學會使用 IDE，掌握介面結構和高效提示方式</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/building-prototype/">初級三：動手做出原型</a></td><td style="text-align:left;">從產品分析拆解，到多頁面產品原型實現的完整閉環</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/integrating-ai-capabilities/">初級四：給原型加上 AI 能力</a></td><td style="text-align:left;">理解並完成常見 AI 能力（文字圖片影片）的 API 接入</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/complete-project-practice/">初級五：完整專案實戰</a></td><td style="text-align:left;">模擬真實場景、接受使用者反饋迭代並完成專案展示（含大作業）</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="附錄" tabindex="-1">附錄 <a class="header-anchor" href="#附錄" aria-label="Permalink to “附錄”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章節</th><th style="text-align:left;">關鍵內容</th><th style="text-align:left;">狀態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/appendix-a-product-thinking/">附錄A：產品思維補充</a></td><td style="text-align:left;">從想法評估到需求拆解與 MVP 的產品思維框架</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/appendix-b-common-errors/">附錄B：常見報錯及解決方案</a></td><td style="text-align:left;">vibe coding 中的常見錯誤及排查方法</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/appendix-idea-sources/">附錄：從哪裡找點子</a></td><td style="text-align:left;">從參考應用、趨勢和 VC 清單裡收出細分方向</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/appendix-double-diamond/">附錄：雙鑽模型</a></td><td style="text-align:left;">理解先定義問題，再展開方案設計的完整節奏</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/appendix-jobs-to-be-done/">附錄：Jobs to Be Done</a></td><td style="text-align:left;">用 JTBD 方法看清使用者真正想完成的事</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-1/appendix-mom-test/">附錄：The Mom Test 使用者訪談法</a></td><td style="text-align:left;">透過使用者訪談驗證需求的調研方法</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="二、初中級開發工程師" tabindex="-1">二、初中級開發工程師 <a class="header-anchor" href="#二、初中級開發工程師" aria-label="Permalink to “二、初中級開發工程師”">​</a></h3><h4 id="前端部分" tabindex="-1">前端部分 <a class="header-anchor" href="#前端部分" aria-label="Permalink to “前端部分”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章節</th><th style="text-align:left;">關鍵內容</th><th style="text-align:left;">狀態</th></tr></thead><tbody><tr><td style="text-align:left;">使用 lovart 生產素材</td><td style="text-align:left;">學會用 lovart 批次生成人物、場景等視覺素材，為 UI 設計和前端開發提供素材基礎</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Figma 與 MasterGo 入門</td><td style="text-align:left;">用設計工具梳理資訊架構和頁面結構，為前端實現打基礎</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">構建第一個現代應用程式-UI 設計</td><td style="text-align:left;">基於設計稿完成元件化介面，實現從設計到程式碼的第一條鏈路</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">參考 UI 設計規範設計頁面和按鈕</td><td style="text-align:left;">學習用主流設計規範組織頁面結構、按鈕層級，並藉助 AI 生成設計方案</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-2/frontend/hogwarts-portraits/">一起做霍格沃茨畫像</a></td><td style="text-align:left;">從 0 到 1 做出接入 AI 能力的前端應用，串聯設計與開發</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="後端開發部分" tabindex="-1">後端開發部分 <a class="header-anchor" href="#後端開發部分" aria-label="Permalink to “後端開發部分”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章節</th><th style="text-align:left;">關鍵內容</th><th style="text-align:left;">狀態</th></tr></thead><tbody><tr><td style="text-align:left;">什麼是 API</td><td style="text-align:left;">理解 HTTP 介面與請求響應模型，為後端整合與聯調做準備</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-2/backend/database-supabase/">從資料庫到 Supabase</a></td><td style="text-align:left;">在 Supabase 上落地資料庫和 API，打通資料模型與前端頁面</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">大模型輔助編寫介面程式碼與介面文件</td><td style="text-align:left;">用大模型協助生成介面與資料庫文件及程式碼，實現可讀可測的後端</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Git 工作流與 Zeabur 部署</td><td style="text-align:left;">在 Git 工作流中管理程式碼，並將應用部署到 Zeabur 上線</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">現代 CLI 開發工具</td><td style="text-align:left;">使用 CLI 類 AI 程式設計工具加速開發與除錯，形成個人工程化工作流</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">如何整合 stripe 等收費系統</td><td style="text-align:left;">接入支付系統，完成收費鏈路與基礎結算流程</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">構建第一個現代應用程式-全棧應用</td><td style="text-align:left;">綜合前端、後端與支付模組，完成可上線的全棧 Web 應用</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">現代前端元件庫 + Trae 實戰</td><td style="text-align:left;">使用現代前端元件庫與 Trae，獨立完成可登入註冊並支援收費的產品</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="ai-能力附錄" tabindex="-1">AI 能力附錄 <a class="header-anchor" href="#ai-能力附錄" aria-label="Permalink to “AI 能力附錄”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">章節</th><th style="text-align:left;">關鍵內容</th><th style="text-align:left;">狀態</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/zh-tw/stage-2/ai-capabilities/dify-knowledge-base/">Dify 入門與知識庫整合</a></td><td style="text-align:left;">用 Dify Workflow 與基礎 RAG 搭建工具類產品，為後續應用升級打樣</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">學會查詢 AI 詞典與整合多模態 API</td><td style="text-align:left;">學會查詢合適的模型與 API，並把文字、影象等多模態能力接入產品</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="三、高階開發工程師" tabindex="-1">三、高階開發工程師 <a class="header-anchor" href="#三、高階開發工程師" aria-label="Permalink to “三、高階開發工程師”">​</a></h3>',24)])])}const o=e(d,[["render",n]]);export{x as __pageData,o as default};
